// VULNERABLE POLICY: too broad, enables escalation
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "sts:AssumeRole",
      "Resource": "*"          // Can become ANY role - dangerous
    },
    {
      "Effect": "Allow",
      "Action": "iam:PassRole",
      "Resource": "*"          // Can hand ANY role to a new service
    }
  ]
}

// SECURE POLICY: scoped and conditional (least privilege)
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Action": "sts:AssumeRole",
      "Resource": "arn:aws:iam::123456789012:role/SpecificTaskRole"
    },
    {
      "Effect": "Allow",
      "Action": "iam:PassRole",
      "Resource": "arn:aws:iam::123456789012:role/SageMakerRole-project-x",
      "Condition": {
        "StringEquals": {
          "iam:PassedToService": "sagemaker.amazonaws.com"
        }
      }
    }
  ]
}
// Why better:
// - AssumeRole is limited to ONE role, not everything
// - PassRole is limited to ONE role AND only to one service
// - No wildcards means no surprise escalation paths
